#include "edudb.hpp"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <set>
using namespace edudb;namespace fs=std::filesystem;
namespace {
std::size_t checks=0;json observations=json::array();
void need(bool b,const std::string& why){++checks;if(!b)throw std::runtime_error(why);}
template<class F>void error(const std::string& code,F f){try{f();}catch(const DbError& e){need(e.code==code,"Expected "+code+", got "+e.code);return;}throw std::runtime_error("Missing "+code);}
TransactionOptions record(){TransactionOptions o;o.record_locks=true;return o;}
void access(Storage& db,const std::shared_ptr<Transaction>& tx,bool write=false){db.refresh_read_view(tx,{{"t",true,write,false}});}
StoredRow find(Storage& db,const std::shared_ptr<Transaction>& tx,int id){ScanSpec spec;spec.index="pk";spec.lower=spec.upper=id;auto c=db.scan(tx,"t",spec);StoredRow row;need(c->next(row),"Primary scan target exists");return row;}
json definition(){json rows=json::array();for(int i=0;i<200;++i)rows.push_back(json::array({i,i}));return {{"columns",json::array({{{"name","id"},{"type","INTEGER"},{"not_null",true}},{{"name","v"},{"type","INTEGER"}}})},{"indexes",json::array({{{"name","pk"},{"columns",json::array({"id"})},{"method","BPLUS"},{"unique",true},{"options",{{"max_keys",5}}}}})},{"rows",rows}};}
void run(const fs::path& path){Storage db(path.u8string(),3);auto seed=db.begin();db.write_table(seed,"t",definition());db.commit(seed);
    auto reader=db.begin(record());access(db,reader);ScanSpec spec;spec.index="pk";spec.lower=0;spec.upper=199;auto cursor=db.scan(reader,"t",spec);StoredRow row;need(cursor->next(row)&&row.values[0]==0,"Old cursor opened and first row actually read");auto old=db.inspect(reader,"t","pk")["structure"]["descriptor"];auto writer=db.begin(record());access(db,writer,true);for(int id=200;id<650;++id)db.insert_row(writer,"t",json::array({id,id}));db.commit(writer);
    std::set<int> old_ids{0};while(cursor->next(row)){need(row.values[0].get<int>()<200,"Live cursor does not see new split pages or newly inserted rows");need(old_ids.insert(row.values[0].get<int>()).second,"Old cursor does not repeat retired/split index entries");}need(old_ids.size()==200,"Old cursor retains exact pre-commit physical leaf chain");cursor.reset();auto pinned_stats=db.diagnostics();need(pinned_stats["transactions"]["history_bytes"]>0,"Record statement really retained historical page images");
    access(db,reader);auto now=db.read_table(reader,"t",false,false);need(now["row_count"]==650,"Next record statement refreshes committed descriptor view");auto expanded=db.inspect(reader,"t","pk")["structure"]["descriptor"];need(expanded["height"]>=old["height"],"Actual tree remains valid after extensive split publication");observations.push_back({{"kind","record_statement_physical_cursor"},{"old_rows",old_ids.size()},{"next_statement_rows",now["row_count"]},{"old_descriptor",old},{"new_descriptor",expanded},{"transactions",pinned_stats["transactions"]}});db.commit(reader);
    auto a=db.begin(record()),b=db.begin(record());access(db,a,true);access(db,b,true);auto ra=find(db,a,1),rb=find(db,b,2);need(ra.id.page_id==rb.id.page_id,"Conflict fixture really uses two RIDs on one HEAP page");ra.values[1]=101;rb.values[1]=202;db.update_row(a,"t",ra.id,ra.values);db.update_row(b,"t",rb.id,rb.values);db.commit(a);auto before=db.diagnostics()["wal_bytes"];error("SERIALIZATION_FAILURE",[&]{db.commit(b);});need(db.diagnostics()["wal_bytes"]==before,"Same-page conflict rejected before appending WAL");need(!db.recovery_required(),"Conservative conflict is not an I/O fail-stop");db.rollback(b);auto inspect=db.begin();access(db,inspect);need(find(db,inspect,1).values[1]==101&&find(db,inspect,2).values[1]==2,"Loser does not overwrite committed disjoint row");db.commit(inspect);
    for(auto protocol:{TransactionProtocol::Snapshot,TransactionProtocol::Occ,TransactionProtocol::Timestamp,TransactionProtocol::Thomas}){auto o=record();o.protocol=protocol;error("INVALID_LOCK_GRANULARITY",[&]{db.begin(o);});}
}
void aries(const fs::path& path){StorageOptions options;options.recovery_mode="ARIES_PAGE";Storage db(path.u8string(),3,32u*1024u*1024u,options);error("ARIES_RECORD_UNSUPPORTED",[&]{db.begin(record());});need(db.diagnostics()["active_transactions"]==0,"Rejected ARIES_RECORD leaves no active transaction");need(!db.recovery_required(),"Unsupported mode does not poison ARIES engine");}
}
int main(){auto path=fs::temp_directory_path()/("edudb-range-snapshot-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));try{fs::create_directory(path);std::ofstream(path/"owned-test.marker")<<"range physical snapshot";run(path/"redo");aries(path/"aries");need(fs::equivalent(path.parent_path(),fs::temp_directory_path())&&path.filename().string().rfind("edudb-range-snapshot-",0)==0&&fs::exists(path/"owned-test.marker"),"Owned cleanup");fs::remove_all(path);std::cout<<"OBSERVATIONS "<<observations.dump()<<"\nPASS range physical snapshot "<<checks<<" checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL range snapshot after "<<checks<<": "<<e.what()<<"; evidence "<<path.u8string()<<"\n";return 1;}}
